function drawBedHint(){const bed=game.houseItems.find(o=>o.id==='bed'&&o.room==='bedroom');if(!bed||sleepCycle?.phase==='nightfall'||sleepCycle?.phase==='sleeping'||sleepCycle?.phase==='morning'||!game.heroes.some(p=>Math.abs(p.x-bed.x)<155))return;const x=bed.x-game.camera,y=scenes.bedroom.ground-91;ctx.fillStyle='#fff4df';ctx.strokeStyle='#71583f';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(x-80,y-13,160,25,6);ctx.fill();ctx.stroke();ctx.font='bold 10px Nunito,system-ui';ctx.textAlign='center';ctx.fillStyle='#594636';const label=sleepCycle?'E — Лечь рядом / пригласить':'E — Лечь спать';ctx.fillText(label,x,y+3)}
