game.camera=0;if(houseRooms.includes(game.scene)){let used=[];game.heroes.forEach((p,i)=>{if(game.houseItems.some(o=>o.room===game.scene&&Math.abs(o.x-p.x)<=(furnitureDefs[o.id]?.w||40)/2+10))p.x=findClearSpot(i?790:820,used);used.push(p.x)})}game.heroes.forEach(p=>{p.y=p.y||0;p.vx=0;p.facing=p.facing||1;p.jumpTime=0;p.jumpY=0;p.anim={state:'idle',from:'idle',time:0,fromTime:0,blend:1}});
