function beginSleep(indices){const bed=game.houseItems.find(o=>o.id==='bed'&&o.room==='bedroom');if(game.scene!=='bedroom'||!bed){notify('Спать можно только в спальне у кровати.');return}if(sleepCycle&&['nightfall','sleeping','morning'].includes(sleepCycle.phase)){notify('Ночь уже завершается.');return}if(!sleepCycle)sleepCycle={scene:'bedroom',bedX:bed.x,members:[],phase:'waiting',elapsed:0,counted:false,dayAtStart:game.day};for(const index of indices){if(sleepCycle.members.includes(index))continue;const p=game.heroes[index];if(!p)continue;sleepCycle.members.push(index);p.sleepState='approaching';p.sleepSide=index===0?'left':'right';p.sleepTimer=0;p.action=null;p.actionTime=0;p.jumpTime=0;p.approach={x:bed.x+(index===0?-27:27),sleepBed:true};p.facing=index===0?1:-1}sleepCycle.phase='waiting';closeModal();notify(indices.length>1?'Персонажи идут к одной кровати…':`Персонаж подходит к кровати. Можно пригласить ${game.heroes[1-indices[0]].name} лечь рядом.`)}
function finishNight(){if(!sleepCycle||!sleepCycle.members.some(i=>game.heroes[i].sleepState==='sleeping')){notify('Сначала одному из персонажей нужно лечь.');return}if(['nightfall','sleeping','morning'].includes(sleepCycle.phase))return;sleepCycle.phase='nightfall';sleepCycle.elapsed=0;sleepCycle.startMinute=game.minute;keys={};if(modalOpen())closeModal();save()}
