function updateSleep(dt){if(!sleepCycle)return;for(const i of sleepCycle.members){const p=game.heroes[i];if(p.sleepState==='settling'){p.sleepTimer=Math.max(0,p.sleepTimer-dt/60);if(!p.sleepTimer){p.sleepState='sleeping';p.action='sleep';p.facing=i===0?1:-1;}}}if(sleepCycle.phase==='waiting'&&sleepCycle.members.length===2&&sleepCycle.members.every(i=>game.heroes[i].sleepState==='sleeping'))finishNight();if(sleepCycle.phase==='nightfall'){sleepCycle.elapsed+=dt/60;const progress=clamp(sleepCycle.elapsed/.85,0,1),start=sleepCycle.startMinute||0;game.minute=(start+((1430-start+1440)%1440)*progress)%1440;if(sleepCycle.elapsed>=.85){sleepCycle.phase='sleeping';sleepCycle.elapsed=0}}else if(sleepCycle.phase==='sleeping'){sleepCycle.elapsed+=dt/60;if(sleepCycle.elapsed>=1.05&&!sleepCycle.counted){sleepCycle.counted=true;game.day=Math.max(Math.max(1,Math.floor(+game.day||1)),Math.max(1,Math.floor(+sleepCycle.dayAtStart||1))+1);game.minute=480;game.needs.forEach(n=>n.energy=100);sleepCycle.phase='morning';sleepCycle.elapsed=0;for(const p of game.heroes)if(p.sleepState==='sleeping'){p.sleepState='waking';p.sleepTimer=.85}save();refresh()}}else if(sleepCycle.phase==='morning'){sleepCycle.elapsed+=dt/60;for(const i of sleepCycle.members){const p=game.heroes[i];if(p.sleepState==='waking'){p.sleepTimer=Math.max(0,p.sleepTimer-dt/60);if(!p.sleepTimer){p.sleepState=null;p.action=null;p.actionTime=0;p.sleepSide=null;p.vx=0}}}if(sleepCycle.elapsed>=1.15){for(const p of game.heroes){p.sleepState=null;p.sleepTimer=0;p.action=null;p.actionTime=0;p.approach=null;p.vx=0}sleepCycle=null;keys={};save();refresh();notify(`День ${game.day} — доброе утро! Энергия восстановлена.`)}}}
