document.body.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.menu==='romance')romanceMenu();if(b.dataset.menu==='main')mainMenu();if(b.hasAttribute('data-main-menu')){closeModal();mainMenu()}if(b.dataset.romance){if(b.dataset.romance==='handhold'&&game.holdingHands){closeModal();releaseHands();return}const data={talk:[3,'Вы поговорили по душам.'],compliment:[3,'Тёплый комплимент поднял настроение.'],joke:[2,'Вы вместе посмеялись.'],hug:[5,'Объятия сделали этот день теплее.'],handhold:[4,'Вы прогулялись, держась за руки.'],kiss:[6,'Нежный поцелуй останется приятным воспоминанием.'],sit:[3,'Тихий отдых рядом помог вам сблизиться.']}[b.dataset.romance];closeModal();beginPair(b.dataset.romance,data[0],data[1])}if(b.dataset.gift){const item=game.inventory.find(x=>x.id===b.dataset.gift&&x.count>0);if(!item){notify('Этот предмет уже закончился.');return}const name=item.name;item.count--;if(item.count===0)game.inventory=game.inventory.filter(x=>x!==item);closeModal();beginPair('compliment',item.id==='flower'?9:5,`${name} стал приятным подарком!`);save()}if(b.dataset.date){const id=b.dataset.date;if(!['park','cafe'].includes(id))return;closeModal();go(id,true)}});
document.body.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.shopTab){shop(b.dataset.shopTab);return}if(b.dataset.sell){sellFish(b.dataset.sell);return}if(b.hasAttribute('data-sell-all')){sellAllFish();return}});
document.body.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.menu==='kitten'){kittenMenu();return}if(b.dataset.kittenFeed){selectKittenFood(b.dataset.kittenFeed);return}if(b.hasAttribute('data-kitten-confirm-feed')){confirmKittenFeed();return}if(b.dataset.kittenPlay){startKittenGame(b.dataset.kittenPlay);return}if(b.dataset.kittenAction){const action=b.dataset.kittenAction;if(action==='sleep'){toggleKittenSleep();kittenMenu();return}if(action==='games'){kittenGamesMenu();return}if(action==='back'){game.kitten.pendingFish=null;kittenMenu();return}if(action==='status'){notify(`Сытость ${Math.round(game.kitten.fullness)}, настроение ${Math.round(game.kitten.mood)}, доверие ${Math.round(game.kitten.trust)} из 100.`);return}if(action==='pet'){const hero=game.heroes[game.active],pet=game.kitten,direction=Math.sign(pet.x-hero.x)||1;pet.action='idle';pet.actionTime=0;if(Math.abs(hero.x-pet.x)>34){hero.approach={x:clamp(pet.x-direction*26,25,scenes[game.scene].width-25),object:'__pet_kitten'};hero.facing=direction;closeModal();notify(`${hero.name} подходит погладить котёнка…`)}else{completeKittenPet(game.active);closeModal()}return}if(action==='call'){const hero=game.heroes[game.active];game.kitten.action='call';game.kitten.actionTime=.8;game.kitten.facing=Math.sign(hero.x-game.kitten.x)||1;if(Math.abs(hero.x-game.kitten.x)>190)game.kitten.x=kittenClearX(hero.x-(hero.facing||1)*52);save();closeModal();notify(`${hero.name} позвал${game.active===0?'а':''} котёнка. Тот спешит рядом!`);return}}});
const stock=[{id:'tea',name:'Чай с мёдом',icon:'☕',price:12,effect:'hunger'},{id:'flower',name:'Полевой букет',icon:'✿',price:18,effect:'love'},{id:'cake',name:'Кусочек торта',icon:'🍰',price:20,effect:'happy'},{id:'plant',name:'Комнатный цветок',icon:'♧',price:35,effect:'furniture'},{id:'lamp',name:'Тёплый торшер',icon:'✧',price:48,effect:'furniture'},{id:'armchair',name:'Мягкое кресло',icon:'▰',price:52,effect:'furniture'},{id:'bookshelf',name:'Книжный шкаф',icon:'▤',price:68,effect:'furniture'},{id:'chair',name:'Деревянный стул',icon:'▰',price:24,effect:'furniture'},{id:'coffee_table',name:'Журнальный столик',icon:'▱',price:38,effect:'furniture'},{id:'kitten_bed',name:'Лежанка котёнка',icon:'⌂',price:34,effect:'furniture'},{id:'kitten_bowl',name:'Миска котёнка',icon:'◡',price:12,effect:'furniture'},{id:'yarn_toy',name:'Клубок',icon:'●',price:8,effect:'furniture'},{id:'cat_ball',name:'Мягкий мячик',icon:'●',price:16,effect:'furniture'},{id:'feather_toy',name:'Игрушка с пером',icon:'✦',price:22,effect:'furniture'}];
