function sellFish(instanceId){const index=game.inventory.findIndex(i=>i.instanceId===instanceId&&i.kind&&fishKinds.some(f=>f.id===i.kind));if(index<0){notify('Этой рыбы уже нет в рюкзаке.');shop('sell');return}const fish=game.inventory[index],value=fishSaleValue(fish),oldMoney=game.money,oldItem=fish;game.inventory.splice(index,1);game.money+=value;if(!save()){game.inventory.splice(index,0,oldItem);game.money=oldMoney;shop('sell');return}refresh();shop('sell');notify(`Рыба продана за ${value} монет.`)}
function sellAllFish(){const fish=game.inventory.filter(i=>i.instanceId&&i.kind&&fishKinds.some(f=>f.id===i.kind));if(!fish.length){notify('Рыбы для продажи нет.');shop('sell');return}const total=fish.reduce((sum,item)=>sum+fishSaleValue(item),0);if(!confirm(`Продать ${fish.length} шт. за ${total} монет?`))return;const previous=game.inventory,oldMoney=game.money;game.inventory=game.inventory.filter(i=>!fish.includes(i));game.money+=total;if(!save()){game.inventory=previous;game.money=oldMoney;shop('sell');return}refresh();shop('sell');notify(`Продано рыб: ${fish.length}. Получено: ${total} монет.`)}
function shop(tab='buy'){let rows=stock.map(x=>`<div class="item"><div>${x.icon} ${x.name}<small>Цена: ${x.price} ◈</small></div><button data-buy="${x.id}" ${game.money < x.price ? 'disabled title="Не хватает монет"' : ''}>Купить</button></div>`).join('');const fish=game.inventory.filter(i=>i.instanceId&&i.kind&&fishKinds.some(f=>f.id===i.kind)),saleRows=fish.map(i=>`<div class="item sale-fish"><canvas class="sale-fish-icon" width="76" height="54" data-fish-preview="${escapeHtml(i.kind)}" aria-label="${escapeHtml(i.name)}"></canvas><div>${escapeHtml(i.name)}<small>${i.length} см · ${escapeHtml(i.rarity||'Обычная')}</small></div><b>${fishSaleValue(i)} ◈</b><button data-sell="${escapeHtml(i.instanceId)}">Продать</button></div>`).join('')||'<p>У тебя пока нет рыбы для продажи.</p>';openModal('Лавка у площади',`<p>Ваш кошелёк: <b>${game.money} ◈</b>. Здесь найдутся маленькие радости.</p><div class="actions shop-tabs"><button class="${tab==='buy'?'primary':'soft'}" data-shop-tab="buy">Купить</button><button class="${tab==='sell'?'primary':'soft'}" data-shop-tab="sell">Продать рыбу (${fish.length})</button></div>${tab==='buy'?`<div class="item-list">${rows}</div>`:`<div class="actions"><button class="soft" data-sell-all ${fish.length?'':'disabled'}>Продать всё · ${fish.reduce((sum,i)=>sum+fishSaleValue(i),0)} ◈</button></div><div class="item-list">${saleRows}</div>`}`);if(tab==='sell')$('#modalContent').querySelectorAll('[data-fish-preview]').forEach(canvas=>{const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;drawPixelFish(c,12,7,52,canvas.dataset.fishPreview,0,false,'catch')})}
function kittenBars(){const p=game.kitten;return `<div class="kitten-bars">${[['Сытость','fullness','fullness'],['Настроение','mood','mood'],['Доверие','trust','trust']].map(([label,key,klass])=>`<div class="kitten-meter"><span>${label}</span><div class="meter"><i class="${klass}" style="width:${Math.round(p[key])}%"></i></div><b>${Math.round(p[key])}</b></div>`).join('')}</div>`}
