function selectKittenFood(instanceId){const item=game.inventory.find(i=>i.instanceId===instanceId&&i.kind&&fishKinds.some(f=>f.id===i.kind));if(!item){notify('Этой рыбы уже нет в рюкзаке.');kittenMenu();return}game.kitten.pendingFish=instanceId;openModal('Покормить котёнка?',`<div class="kitten-confirm"><canvas id="kittenFeedPreview" width="180" height="112" aria-label="${escapeHtml(item.name)}"></canvas><p><b>${escapeHtml(item.name)}</b> · ${item.length} см</p><p>Эта рыбка будет израсходована. Котёнок станет сытнее.</p><div class="actions"><button class="primary" data-kitten-confirm-feed>Покормить</button><button class="soft" data-kitten-action="back">Назад</button></div></div>`);const c=$('#kittenFeedPreview').getContext('2d');c.imageSmoothingEnabled=false;drawPixelFish(c,48,25,84,item.kind,0,false,'catch')}
function confirmKittenFeed(){const id=game.kitten.pendingFish,index=game.inventory.findIndex(i=>i.instanceId===id&&i.kind&&fishKinds.some(f=>f.id===i.kind));if(index<0){game.kitten.pendingFish=null;notify('Рыбы для кормления больше нет.');kittenMenu();return}const oldItem=game.inventory[index],oldPet={...game.kitten},oldInventory=game.inventory;game.inventory.splice(index,1);game.kitten.fullness=clamp(game.kitten.fullness+34,0,100);game.kitten.mood=clamp(game.kitten.mood+7,0,100);game.kitten.trust=clamp(game.kitten.trust+2,0,100);game.kitten.pendingFish=null;game.kitten.action='walk_food';game.kitten.actionTime=0;game.kitten.foodX=kittenClearX(clamp(game.heroes[game.active].x-(game.heroes[game.active].facing||1)*27,24,scenes[game.scene].width-24));game.kitten.eatWarmup=.55;if(!save()){game.inventory=oldInventory;game.kitten=oldPet;kittenMenu();return}closeModal();refresh();notify(`${oldItem.name} отправилась в миску. Котёнок довольно мурлычет.`)}
function startKittenGame(kind){if(!['yarn','ball','feather'].includes(kind))return;const p=game.kitten;p.action='play';p.actionTime=3.8;p.playKind=kind;p.playX=clamp(game.heroes[game.active].x+(game.heroes[game.active].facing||1)*45,25,scenes[game.scene].width-25);p.mood=clamp(p.mood+20,0,100);p.trust=clamp(p.trust+4,0,100);save();closeModal();refresh();notify(kind==='yarn'?'Котёнок гоняется за клубком!':kind==='ball'?'Котёнок ловит мягкий мячик!':'Котёнок прыгает за ленточкой!')}
function kittenGamesMenu(){openModal('Поиграть с котёнком',`<p>Выбери игрушку — игра длится несколько секунд, управление останется доступно.</p><div class="item-list"><div class="item"><div>Клубок<small>Котёнок гоняется за катящейся нитью</small></div><button data-kitten-play="yarn">Играть</button></div><div class="item"><div>Мягкий мячик<small>Котёнок подпрыгивает и догоняет мяч</small></div><button data-kitten-play="ball">Играть</button></div><div class="item"><div>Ленточка<small>Котёнок ловит порхающую игрушку</small></div><button data-kitten-play="feather">Играть</button></div></div>`)}
function mapMenu(){openModal('Куда отправимся?',`<p>Выберите место для прогулки. В каждом уголке есть свои занятия.</p><div class="item-list">${[['home','⌂','Наш дом'],['bedroom','☾','Спальня'],['kitchen','♨','Кухня'],['bathroom','♧','Ванная'],['street','⌖','Уютная улица'],['park','♧','Тихий парк'],['fishing','≈','Речная заводь · рыбалка'],['cafe','☕','Кафе «Тёплый мёд»'],['shop','✿','Лавка у площади'],['anniversary','♡','Наше место · годовщина']].map(([id,icon,n])=>`<div class="item"><div>${icon} ${n}</div><button data-go="${id}">Пойти</button></div>`).join('')}</div>`)}
const anniversaryDefault=()=>`${annName(0)}, с нашей первой годовщиной! ❤️\n\nЦелый год вместе — и как же здорово, что в моей жизни есть именно ты.\n\nСпасибо тебе за наши моменты, за улыбки, за тепло и за всё то, что делает нашу историю особенной.\n\nЯ хочу, чтобы впереди у нас было ещё много счастливых дней, прогулок, объятий, маленьких приключений и воспоминаний, которые мы будем создавать вместе.\n\nЭтот маленький мир — наша история в миниатюре. Здесь есть места, куда мы можем возвращаться, приключения, которые можем переживать вместе, и самое главное — мы с тобой.\n\nЯ не знаю, что приготовит нам будущее, но мне хочется продолжать открывать его вместе с тобой.\n\nСпасибо, что ты есть в моей жизни. ❤️\n\nС нашей первой годовщиной. Пусть это будет только начало нашей большой истории.`;
function startAnniversary(){if(game.anniversary.started){closeModal();go('anniversary');return}openModal('Особый вечер',`<p><b>${escapeHtml(annName(1))}</b> зовёт <b>${escapeHtml(annName(0))}</b> на особенный вечер: прогулку по вашему месту, маленький подарок и письмо.</p><div class="actions"><button class="primary" data-anniversary-start>Начать вечер</button><button class="soft" data-anniversary-skip>Пропустить вступление</button><button class="soft" data-resume>Позже</button></div>`)}
function beginAnniversary(skip=false){game.anniversary.started=true;game.anniversary.giftOpening=0;closeModal();go('anniversary');if(!skip)openModal('Приглашение',`<div class="anniversary-dialogue"><p>«${escapeHtml(annName(0))}, сегодня у нас особенный день. Я хочу провести этот вечер рядом с тобой — пойдём в наше место?»</p><p class="ann-signature">— ${escapeHtml(annName(1))}</p></div><div class="actions"><button class="primary" data-anniversary-walk>Пойдём вместе</button><button class="soft" data-resume>Поговорить там</button></div>`);save()}
function anniversaryMenu(){const a=game.anniversary;openModal('Наше место',`<p>Вечерний сад ждёт вас. Можно прогуляться, поговорить, сесть на скамейку или открыть подарок.</p><div class="actions"><button class="primary" data-anniversary-couple="talk">Поговорить вдвоём</button><button class="soft" data-anniversary-couple="sit">Сесть рядом на скамейке</button><button class="soft" data-anniversary-gift>${a.presentOpened?'Посмотреть подарок':'Открыть подарок'}</button><button class="soft" data-letter>Прочитать письмо</button>${a.presentOpened?'<button class="soft" data-anniversary-finale>Завершить вечер</button>':''}</div>`)}
function openAnniversaryGift(){const a=game.anniversary;if(a.presentOpened){giftMenu();return}if(a.giftOpening)return;a.giftOpening=performance.now();notify('Коробка медленно открывается…');setTimeout(()=>{a.giftOpening=0;a.presentOpened=true;if(!game.inventory.some(i=>i.id==='anniversary_bouquet'))game.inventory.push({id:'anniversary_bouquet',name:'Праздничный букет',count:1,icon:'✿',price:0});save();refresh();openModal('Подарок',`<div class="gift-reveal"><div class="pixel-bouquet">✿</div><p>Под крышкой — букет цветов и письмо. Букет теперь хранится в рюкзаке.</p></div><div class="actions"><button class="primary" data-letter>Прочитать письмо</button><button class="soft" data-resume>Осмотреть букет</button><button class="soft" data-anniversary-finale>Завершить вечер</button></div>`);},820)}
function giftMenu(){openModal('Подарок на память',`<div class="gift-reveal"><div class="pixel-bouquet">✿</div><p>Праздничный букет — подарок из вашего особенного вечера. Он лежит в рюкзаке.</p></div><div class="actions"><button class="primary" data-letter>Перечитать письмо</button>${game.anniversary.finalDone?'':'<button class="soft" data-anniversary-finale>Завершить вечер</button>'}<button class="soft" data-resume>Закрыть</button></div>`)}
function letterMenu(){const body=game.anniversary.letterBody||anniversaryDefault();openModal('С нашей первой годовщиной ❤️',`<article class="anniversary-letter"><div class="letter-to">Адресовано: ${escapeHtml(annName(0))}</div><div id="letterBody" class="letter-body"></div><div class="letter-sign">С любовью,<br><b>${escapeHtml(annName(1))}</b> ❤️</div></article><div class="actions"><button class="primary" data-anniversary-end>Закончить вечер</button></div>`);$('#letterBody').textContent=body.replaceAll('[Имя получателя]',annName(0)).replaceAll('[Имя отправителя]',annName(1))}
function editLetter(){openModal('Ваше послание',`<p>Оставьте поле пустым, чтобы вернуть стандартный текст. Подпись отправителя добавляется отдельно.</p><label class="field">Текст письма<textarea id="ann-letter-edit" rows="10" maxlength="3500" placeholder="Напишите своё послание…">${escapeHtml(game.anniversary.letterBody)}</textarea></label><div class="actions"><button class="primary" data-letter-save>Сохранить письмо</button><button class="soft" data-letter>Отмена</button></div>`)}
function anniversaryInteract(){const p=game.heroes[game.active],delta=865-p.x;if(Math.abs(delta)<68){openAnniversaryGift()}else{p.approach={x:delta>0?823:907,object:'__anniversary_gift'};p.facing=Math.sign(delta);notify('Подходим к праздничной коробке…')}return true}
function chooseFish(){let roll=Math.random()*100;for(const fish of fishKinds){roll-=fish.chance;if(roll<0)return fish}return fishKinds[0]}
function makeFishSpecimen(kind){return {...kind,kind:kind.id,length:Math.round(kind.range[0]+Math.random()*(kind.range[1]-kind.range[0]))}}
function fishingMenu(){
 if(!fishingSession)fishingSession={phase:'idle'};const s=fishingSession;let title='У речной заводи',content='';
 if(s.phase==='idle')content='<p>Возьмите удочку и следите за красно-белым поплавком. Когда он уйдёт под воду, нажмите «Подсечь!» или клавишу E.</p><div class="actions"><button class="primary" data-fish="cast">Взять удочку · закинуть</button><button class="soft" data-fish="leave">Отойти от берега</button></div>';
 else if(s.phase==='waiting')content='<p>Поплавок тихо покачивается на волнах. Рыба может клюнуть в любой момент.</p><div class="actions"><button class="soft" data-fish="wait">Продолжать наблюдать</button><button class="soft" data-fish="cancel">Смотать леску</button></div>';
 else if(s.phase==='nibble'){title='Поплавок дрогнул';content='<p>Кажется, у крючка кто-то есть… следите за поплавком!</p><div class="actions"><button class="soft" data-fish="wait">Ждать поклёвку</button><button class="soft" data-fish="cancel">Смотать леску</button></div>'}
 else if(s.phase==='bite'){title='ПОПЛАВОК УШЁЛ ПОД ВОДУ!';content=`<p class="fish-bite-copy">Подсекайте — рыба на крючке!</p><div class="actions"><button class="primary fish-hook-button" data-fish="hook">ПОДСЕЧЬ! <small>E</small></button></div>`}
 else if(s.phase==='result'&&s.fish){title='Рыба поймана!';content=`<section class="fish-catch"><canvas id="caughtFishPreview" width="360" height="210" aria-label="Пиксельный рисунок пойманной рыбы"></canvas><div class="fish-catch-title"><h3>${escapeHtml(s.fish.name)}</h3><span class="fish-rarity rarity-${s.fish.kind}">${escapeHtml(s.fish.rarity)}</span></div><p>${escapeHtml(s.fish.description)}</p><div class="fish-stats"><span>Длина <b>${s.fish.length} см</b></span><span>Вид <b>${escapeHtml(s.fish.name)}</b></span></div><div class="actions"><button class="primary" data-fish="again">Продолжить рыбалку</button><button class="soft" data-fish="leave">Закончить рыбалку</button></div></section>`}
 else if(s.phase==='result')content=`<p>${escapeHtml(s.message||'Рыбка сорвалась — попробуйте ещё раз.')}</p><div class="actions"><button class="primary" data-fish="again">Продолжить рыбалку</button><button class="soft" data-fish="leave">Закончить рыбалку</button></div>`;
 else content='<p>Леска натянулась! Рыба сопротивляется — вываживаем её к берегу.</p><div class="actions"><button class="soft" disabled>Вываживание…</button></div>';
 openModal(title,content);if(s.phase==='bite')$('#modal').classList.add('fish-bite-modal');else $('#modal').classList.remove('fish-bite-modal');
}
function paintCaughtFish(t){const canvas=$('#caughtFishPreview');if(!canvas||!fishingSession?.fish)return;const c=canvas.getContext('2d'),fish=fishingSession.fish,data=fishKinds.find(f=>f.id===fish.kind)||fishKinds[0],ratio=fish.length/((data.range[0]+data.range[1])/2),size=clamp(200*ratio,155,270);c.imageSmoothingEnabled=false;c.clearRect(0,0,canvas.width,canvas.height);const pulse=Math.sin(t/320)*2;c.fillStyle='#e8f0df';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#c9dfd2';for(let i=0;i<9;i++)c.fillRect(i*46+((t/50)%46),143+(i%3)*13,27,3);c.fillStyle='#fff8df';c.fillRect(17,16,canvas.width-34,canvas.height-32);c.strokeStyle='#b99567';c.lineWidth=4;c.strokeRect(19,18,canvas.width-38,canvas.height-36);drawPixelFish(c,(canvas.width-size)/2,17+pulse,size,fish.kind,t/1000,Math.sin(t/700)>0,'catch');c.fillStyle='#6b8270';c.fillRect(75,201,210,2);c.fillStyle='#fff';c.fillRect(95,43,34,3);}
function castFishing(){if(!fishingSession||!['idle','result'].includes(fishingSession.phase))return;fishingSession={phase:'casting',elapsed:0,variant:Math.floor(Math.random()*3)};const p=game.heroes[game.active];p.facing=1;p.anim.from=p.anim.state;p.anim.state='cast';closeModal();notify('Замах… поплавок летит к тихой заводи!')}
let fishSerial=0;function landFishingCatch(){const s=fishingSession,fish=s.fish||makeFishSpecimen(chooseFish()),kind=fishKinds.find(f=>f.id===fish.kind)||fishKinds[0],length=fish.length;s.fish=fish;s.phase='result';s.elapsed=0;const instanceId=`fish-${Date.now()}-${++fishSerial}`,id=`fish_${kind.id}_${instanceId}`;game.inventory.push({id,instanceId,kind:kind.id,model:kind.model,name:kind.name,count:1,icon:'≈',price:kind.salePrice,color:kind.colors.body,length,rarity:kind.rarity,description:kind.description});game.needs[game.active].happy=clamp(game.needs[game.active].happy+3,0,100);save();refresh();fishingMenu();notify(`Улов на берегу — ${kind.name}, ${length} см!`)}
function tickFishing(dt){
 const s=fishingSession;if(game.scene!=='fishing'||!s)return;s.elapsed=(s.elapsed||0)+dt/60;const p=game.heroes[game.active];
 if(s.phase==='casting'&&s.elapsed>=.82){s.phase='waiting';s.elapsed=0;s.biteAt=5+Math.random()*4;notify('Поплавок лёг на воду. Ждём поклёвку…')}
 else if(s.phase==='waiting'&&s.elapsed>=s.biteAt){s.phase='nibble';s.elapsed=0;s.variant=Math.floor(Math.random()*3);s.fish=makeFishSpecimen(chooseFish());notify('Поплавок вздрогнул…')}
 else if(s.phase==='nibble'&&s.elapsed>=1.35){s.phase='bite';s.elapsed=0;s.deadline=5.5;notify('Поклёвка! Поплавок уходит под воду — подсеките!');fishingMenu()}
 else if(s.phase==='bite'&&s.elapsed>=s.deadline){s.phase='escaped';s.elapsed=0;s.fish=null;p.action=null;p.anim.state='idle';if(modalOpen())closeModal();notify('Рыбка сорвалась с крючка. Поплавок снова ждёт…')}
 else if(s.phase==='escaped'&&s.elapsed>=1.25){s.phase='waiting';s.elapsed=0;s.fish=null;s.biteAt=4+Math.random()*5}
 else if(s.phase==='setting'&&s.elapsed>=.55){s.phase='fighting';s.elapsed=0;notify('Рыба сопротивляется! Удерживайте леску…')}
 else if(s.phase==='fighting'&&s.elapsed>=2.9){s.phase='landing';s.elapsed=0}
 else if(s.phase==='landing'&&s.elapsed>=.95)landFishingCatch();
 if(p&&['casting','setting','fighting','landing'].includes(s.phase))p.anim.state=s.phase==='casting'?'cast':'reel';
}
function hookFishing(){const s=fishingSession;if(!s||s.phase!=='bite')return;if(s.elapsed>=s.deadline){return}if(!s.fish)s.fish=makeFishSpecimen(chooseFish());s.phase='setting';s.elapsed=0;game.heroes[game.active].anim.state='reel';closeModal();notify('Подсечка! Удочка согнулась — начинаем вываживать!')}
function interact(){if(game.scene==='fishing'){const p=game.heroes[game.active],phase=fishingSession?.phase;if(phase==='bite'){hookFishing();return}if(['casting','setting','fighting','landing'].includes(phase)){notify('Не отпускайте леску — идёт вываживание!');return}if(phase==='result'||phase==='waiting'||phase==='nibble'){fishingMenu();return}if(Math.abs(p.x-530)>85){p.approach={x:470,object:'__fishing_spot'};p.facing=1;notify('Подходим к удобному месту у воды…')}else fishingMenu();return}if(game.scene==='anniversary'){anniversaryInteract();return}if(houseInteract())return;if(Math.abs(game.kitten.x-game.heroes[game.active].x)<64){kittenMenu();return}romanceMenu()}
document.body.addEventListener('click',e=>{const b=e.target.closest('button[data-fish]');if(!b)return;const action=b.dataset.fish;if(action==='cast')castFishing();else if(action==='hook')hookFishing();else if(action==='leave'||action==='cancel'){fishingSession=null;game.heroes.forEach(p=>{if(p.anim?.state==='cast'||p.anim?.state==='reel')p.anim.state='idle'});closeModal();notify('Вы смотали леску. Управление снова свободно.')}else if(action==='wait'){closeModal();notify('Вы наблюдаете за поплавком…')}else if(action==='again'){if(fishingSession?.phase==='result'){fishingSession.phase='idle';fishingSession.fish=null}fishingMenu()}});
function romanceMenu(){const places=[['park','Прогуляться в парке'],['cafe','Сходить в кафе']];const actions=[['talk','Поговорить по душам',3],['compliment','Сказать комплимент',3],['joke','Рассказать шутку',2],['hug','Обняться',5],['handhold','Взяться за руки',4],['kiss','Поцеловаться',6],['sit','Посидеть рядом',3]];let gifts=game.inventory.filter(i=>i.count>0&&!furnitureDefs[i.id]);openModal('Время вдвоём',`<p>Близость: <b>${game.relationship}/100</b>. Выберите настоящее совместное действие.</p><div class="item-list">${actions.map(([id,name])=>`<div class="item"><div>${name}</div><button data-romance="${id}">${id==='handhold'&&game.holdingHands?'Отпустить руки':'Вместе'}</button></div>`).join('')}${gifts.map(i=>`<div class="item"><div>Подарить: ${i.icon||'✿'} ${i.name}<small>В рюкзаке: ${i.count}</small></div><button data-gift="${i.id}">Подарить</button></div>`).join('')||'<p>Нет вещей для подарка. Букет, чай и десерт можно купить в лавке.</p>'}${places.map(([id,name])=>`<div class="item"><div>${name}</div><button data-date="${id}">Пригласить</button></div>`).join('')}<div class="item"><div>Особый вечер годовщины<small>Прогулка, подарок и письмо</small></div><button data-anniversary>Начать</button></div></div>`)}
function releaseHands(showMessage=true){if(!game.holdingHands)return;game.holdingHands=false;game.handholdOffset=0;game.heroes.forEach(p=>{if(p.action==='romance-handhold'){p.action=null;p.actionTime=0;p.anim.state='idle';p.anim.from='idle';p.anim.time=0;p.anim.blend=1}});save();refresh();if(showMessage)notify('Вы отпустили руки.')}
function beginPair(kind,points,message,force=false){if(game.holdingHands&&kind!=='handhold')releaseHands(false);const a=game.active,b=1-a,p=game.heroes[a],q=game.heroes[b],scene=game.scene;if(!force&&['kiss','hug'].includes(kind)&&game.relationship<15){notify('Сначала укрепите близость: поговорите, скажите комплимент или подарите что-нибудь.');return}let mid=clamp((p.x+q.x)/2,50,scenes[scene].width-50),gap=kind==='handhold'?18:kind==='sit'?26:22;let left=mid-gap,right=mid+gap;p.action=null;q.action=null;p.actionTime=0;q.actionTime=0;p.approach={x:a===0?left:right,pair:true};q.approach={x:b===0?left:right,pair:true};p.pairKind=kind;q.pairKind=kind;p.facing=p.x<=q.x?1:-1;q.facing=-p.facing;game.pairRunning={kind,points,message,started:false};notify('Персонажи подходят друг к другу…');save()}
function finishPair(){let pair=game.pairRunning;if(!pair||pair.started)return;pair.started=true;let state={talk:'talk',compliment:'talk',joke:'talk',hug:'hug',handhold:'handhold',kiss:'kiss',sit:'sit'}[pair.kind];const faceRight=game.heroes[0].x<=game.heroes[1].x;game.heroes.forEach((p,i)=>{p.approach=null;p.action=`romance-${pair.kind}`;p.actionTime=pair.kind==='sit'?4:game.anniversary.finalPending==='ending'?5.3:2.1;p.facing=i===0?(faceRight?1:-1):(faceRight?-1:1);p.anim.from=p.anim.state;p.anim.fromTime=p.anim.time;p.anim.state=state;p.anim.time=0;p.anim.blend=0});if(pair.kind==='handhold'){game.holdingHands=true;game.handholdLeader=game.active;game.handholdOffset=game.heroes[1-game.active].x-game.heroes[game.active].x}game.needs.forEach(n=>n.happy=clamp(n.happy+Math.max(1,Math.ceil(pair.points/2)),0,100));game.relationship=clamp(game.relationship+pair.points,0,100);notify(pair.message);save();refresh()}
function need(k,n){let v=game.needs[game.active];v[k]=clamp(v[k]+n,0,100);notify('Самое время немного позаботиться о себе.');refresh()}
function romance(n,msg){game.relationship=clamp(game.relationship+n,0,100);game.needs.forEach(x=>x.happy=clamp(x.happy+Math.ceil(n/2),0,100));notify(msg);refresh();save()}
function decorate(){const owned=game.inventory.filter(i=>furnitureDefs[i.id]&&i.count>0).map(i=>`<div class="item"><div>${i.icon||furnitureDefs[i.id].icon} ${i.name}<small>В рюкзаке: ${i.count}</small></div><button data-place="${i.id}">Разместить</button></div>`).join('');const placed=game.houseItems.map((o,i)=>`<div class="item"><div>${furnitureDefs[o.id].name}<small>${scenes[o.room].name} · x ${Math.round(o.x)}</small></div><button data-move="${i}">Переместить</button></div>`).join('');openModal('Дом и мебель',`<p>Выберите комнату, чтобы поставить новый предмет. Чтобы передвинуть мебель, нажмите «Переместить», затем кликните по свободному месту на полу.</p><div class="actions">${houseRooms.map(id=>`<button class="soft" data-room="${id}">${scenes[id].name.replace('Наш дом · ','')}</button>`).join('')}</div><h3>Мебель в рюкзаке</h3><div class="item-list">${owned||'<p>Пока пусто. Купить мебель можно в магазине.</p>'}</div><h3>Предметы дома</h3><div class="item-list">${placed}</div>`)}
function settings(){openModal('Настройки',`<p>Управление: A / D или ← / → — ходьба, E — действие, Tab — сменить героя. На телефоне используйте кнопки на экране.</p><h3>Имена персонажей</h3><div class="row"><label class="field">Первый герой<input id="setting-name-0" maxlength="40" value="${escapeHtml(game.heroes[0].name)}"></label><label class="field">Второй герой<input id="setting-name-1" maxlength="40" value="${escapeHtml(game.heroes[1].name)}"></label></div><button class="soft" data-save-names>Сохранить имена</button><label class="field"><span>Громкость: <b id="volumeNum">${game.settings.volume}</b>%</span><input id="volume" type="range" min="0" max="100" value="${game.settings.volume}"></label><label class="field"><span><input id="music" type="checkbox" ${game.settings.music?'checked':''}> Атмосферные звуки (звуковой дорожки нет)</span></label><button class="soft" data-reset>Удалить сохранение и начать заново…</button>`)}
document.body.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.menu==='inventory')inventory();if(b.dataset.menu==='wardrobe')wardrobe();if(b.hasAttribute('data-wardrobe-hero')){game.active=Number(b.dataset.wardrobeHero);save();refresh();wardrobe()}if(b.dataset.hairStyle){game.heroes[game.active].hairStyle=b.dataset.hairStyle;save();refresh();wardrobe()}if(b.dataset.outfit){let presets={cardigan:['#d77d72','#596f84'],overalls:['#678c77','#46556a'],dress:['#bd7890','#74536e']};game.heroes[game.active].outfit=b.dataset.outfit;[game.heroes[game.active].shirt,game.heroes[game.active].pants]=presets[b.dataset.outfit];save();refresh();wardrobe()}if(b.dataset.menu==='map')mapMenu();if(b.dataset.menu==='shop')shop();if(b.dataset.menu==='decorate')decorate();if(b.dataset.menu==='settings')settings();if(b.hasAttribute('data-resume'))closeModal();if(b.hasAttribute('data-new')){if(confirm('Начать новую игру? Текущий прогресс будет заменён.')){localStorage.removeItem('our-little-world-save');game=fresh();game.camera=0;closeModal();setup();refresh()}}if(b.hasAttribute('data-begin')){game.heroes[0].name=$('#n1').value.trim();game.heroes[1].name=$('#n2').value.trim();game.heroes[0].skin=$('#skin1').value;game.heroes[0].hair=$('#hair1').value;game.heroes[1].skin=$('#skin2').value;game.heroes[1].hair=$('#hair2').value;closeModal();refresh();save();notify('Добро пожаловать в ваш маленький мир!')}if(b.dataset.go){let id=b.dataset.go;closeModal();go(id)}if(b.dataset.use){let i=game.inventory.find(x=>x.id===b.dataset.use&&x.count>0);if(!i)return; i.count--;if(i.id==='tea'||i.id==='cake')need('hunger',24);if(i.id==='cake')need('happy',10);if(i.id==='flower')romance(5,'Подарок стал поводом для улыбки!');save();inventory();refresh()}if(b.dataset.buy){let i=stock.find(x=>x.id===b.dataset.buy);if(game.money<i.price)return notify('Не хватает монет.');game.money-=i.price;let old=game.inventory.find(x=>x.id===i.id);if(old)old.count++;else game.inventory.push({id:i.id,name:i.name,count:1,icon:i.icon,price:i.price});if(i.effect==='furniture'&&!game.furniture.includes(i.id))game.furniture.push(i.id);if(i.id.startsWith('kitten_')||['yarn_toy','cat_ball','feather_toy'].includes(i.id))game.kitten.owned=[...new Set([...game.kitten.owned,i.id])];$('#moneyLabel').textContent=`◈ ${game.money}`;shop();save();notify(`${i.name} добавлено в ваши вещи!`)}if(b.dataset.place){game.placing=b.dataset.place;closeModal();notify('Кликните по свободному полу, чтобы поставить мебель.')}if(b.dataset.move){let item=game.houseItems[Number(b.dataset.move)];if(item){game.placing={id:item.id,item};closeModal();notify('Кликните по свободному полу, чтобы переместить предмет.')}}if(b.dataset.eat){let food=game.inventory.find(i=>i.id===b.dataset.eat&&i.count>0);if(food){food.count--;game.needs[game.active].hunger=clamp(game.needs[game.active].hunger+28,0,100);closeModal();save();refresh();notify(`Вы поели: ${food.name}.`)}}if(b.dataset.room){let id=b.dataset.room;closeModal();go(id)}if(b.hasAttribute('data-reset')){if(confirm('Удалить только сохранение Our Little World в этом браузере и начать заново?')){localStorage.removeItem('our-little-world-save');game=fresh();game.camera=0;closeModal();refresh();setup()}}});
document.body.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-anniversary'))startAnniversary();if(b.hasAttribute('data-anniversary-start'))beginAnniversary(false);if(b.hasAttribute('data-anniversary-skip'))beginAnniversary(true);if(b.hasAttribute('data-anniversary-walk')){closeModal();beginPair('handhold',5,`Вечер начался — ${annName(0)} и ${annName(1)} идут рядом.`)}if(b.hasAttribute('data-letter'))letterMenu();if(b.hasAttribute('data-anniversary-end')){game.anniversary.finalPending='ending';game.anniversary.fireworksAt=performance.now();game.anniversary.fireworksUntil=performance.now()+5200;closeModal();beginPair('kiss',8,'Вечер заканчивается поцелуем под праздничными огнями.',true)}if(b.dataset.anniversaryCouple){closeModal();beginPair(b.dataset.anniversaryCouple,b.dataset.anniversaryCouple==='sit'?4:5,b.dataset.anniversaryCouple==='sit'?'Вы устроились рядом на скамейке.':'Вы поговорили о том, что дорого вам обоим.')}if(b.hasAttribute('data-anniversary-gift')){closeModal();const p=game.heroes[game.active];if(Math.abs(p.x-865)<68)openAnniversaryGift();else{p.approach={x:p.x<865?823:907,object:'__anniversary_gift'};p.facing=p.x<865?1:-1;notify('Подходим к праздничной коробке…')}}if(b.hasAttribute('data-anniversary-finale')){if(!game.anniversary.presentOpened){notify('Сначала откройте подарок из коробки.');return}closeModal();game.anniversary.finalPending=true;game.anniversary.fireworksAt=performance.now();game.anniversary.fireworksUntil=performance.now()+5200;beginPair('hug',9,'Под звёздами вы обнялись, и в небе зажглись огни.',true)}if(b.hasAttribute('data-save-names')){game.heroes[0].name=$('#setting-name-0').value.slice(0,40);game.heroes[1].name=$('#setting-name-1').value.slice(0,40);save();refresh();settings();notify('Имена персонажей сохранены.')}});document.body.addEventListener('input',e=>{if(e.target.id==='volume'){game.settings.volume=+e.target.value;$('#volumeNum').textContent=e.target.value;save()}});document.body.addEventListener('change',e=>{if(e.target.id==='music'){game.settings.music=e.target.checked;save()}});
canvas.addEventListener('click',e=>{if(game.scene!=='anniversary'||game.anniversary.presentOpened)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*canvas.width/r.width+game.camera,y=(e.clientY-r.top)*canvas.height/r.height,p=game.heroes[game.active];if(Math.abs(x-865)<58&&y>scenes.anniversary.ground-75){const dx=865-p.x;if(Math.abs(dx)<68)openAnniversaryGift();else{p.approach={x:dx>0?823:907,object:'__anniversary_gift'};p.facing=Math.sign(dx);notify('Подходим к праздничной коробке…')}}});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' '].includes(e.key))e.preventDefault();if(e.key==='Escape'){if(modalOpen())closeModal();else $('#pauseBtn').click();return}if(modalOpen()){if(game.scene==='fishing'&&fishingSession?.phase==='bite'&&(e.code==='KeyE'||e.key==='Enter')){e.preventDefault();hookFishing()}return}if(e.code==='Tab'){e.preventDefault();game.active=1-game.active;if(game.holdingHands){game.handholdLeader=game.active;game.handholdOffset=game.heroes[1-game.active].x-game.heroes[game.active].x}game.heroes[game.active].facing=game.heroes[1-game.active].x>=game.heroes[game.active].x?1:-1;refresh()}else if(e.code==='KeyE'||e.key==='Enter')interact();else if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){if(!e.repeat)startJump()}keys[e.code]=true;keys[e.key]=true});window.addEventListener('keyup',e=>{keys[e.code]=false;keys[e.key]=false});window.addEventListener('blur',()=>keys={});document.querySelectorAll('.mobile-controls button').forEach(b=>{let down=e=>{e.preventDefault();if(b.dataset.key){keys[b.dataset.key]=true;return}if(b.dataset.action==='switch'){game.active=1-game.active;if(game.holdingHands){game.handholdLeader=game.active;game.handholdOffset=game.heroes[1-game.active].x-game.heroes[game.active].x}refresh()}if(b.dataset.action==='interact')interact();if(b.dataset.action==='jump')startJump()};let up=()=>{if(b.dataset.key)keys[b.dataset.key]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
window.addEventListener('beforeunload',save);refresh();if(!localStorage.getItem('our-little-world-save'))setup();requestAnimationFrame(draw);requestAnimationFrame(update);
